package com.narada.connection

import java.util.UUID
import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Test

class ChatEngineTest {
    @Test fun queueIsDurableAndClearsDraftInTheSameMutation()=runBlocking<Unit>{val f=ChatFixture();f.engine.saveDraft(f.peerId,"saved");val m=f.queue();assertEquals(ChatStatus.QUEUED,m.status);assertNull(m.envelope);assertTrue(f.memory.document.chat!!.drafts.isEmpty());assertTrue(f.pushed.isEmpty())}
    @Test fun stateAndEnvelopeAreSavedBeforePushAndReceiptBeforeDelivered()=runBlocking<Unit>{val f=ChatFixture();val m=f.queue();f.sync();val s=f.memory.document.chat!!.message(m.id);assertEquals(ChatStatus.DELIVERED,s.status);assertNotNull(s.receipt);assertEquals(listOf(m.text),f.remoteTexts);assertEquals(1,s.attempts)}
    @Test fun repeatedLogicalIdIsIdempotentButDifferentTextConflicts()=runBlocking<Unit>{val f=ChatFixture();val m=f.queue();assertEquals(m,f.queue(m.text,m.id));expectFailure("MESSAGE_ID_CONFLICT"){runBlocking{f.queue("changed",m.id)}};assertEquals(1,f.memory.document.chat!!.messages.size)}
    @Test fun lostPushReplyReusesExactCiphertextAfterReopen()=runBlocking<Unit>{val f=ChatFixture();val m=f.queue();f.afterPush={fail("PEER_TIMEOUT")};expectFailure("PEER_TIMEOUT"){runBlocking{f.sync()}};val e=f.memory.document.chat!!.message(m.id).envelope;f.reopen();f.engine.recover();f.clock+=5000;f.afterPush={};f.sync();assertEquals(e,f.memory.document.chat!!.message(m.id).envelope);assertEquals(2,f.pushed.size);assertEquals(f.pushed[0],f.pushed[1]);assertEquals(1,f.remoteTexts.size);assertEquals(ChatStatus.DELIVERED,f.memory.document.chat!!.message(m.id).status)}
    @Test fun failedRatchetEnvelopeCommitCannotSendOrAdvanceSavedState()=runBlocking<Unit>{val f=ChatFixture();val m=f.queue();val account=f.memory.document.chat!!.account;f.beforeCommit={if(it.chat!!.message(m.id).envelope!=null)f.memory.failWrite=true};expectFailure("STORAGE_UNAVAILABLE"){runBlocking{f.sync()}};assertTrue(f.pushed.isEmpty());assertEquals(account,f.memory.document.chat!!.account);assertTrue(f.memory.document.chat!!.bindings.single().sessions.isEmpty());assertNull(f.memory.document.chat!!.message(m.id).envelope)}
    @Test fun confirmedPrivateInboxAndRatchetPrecedeAcknowledgment()=runBlocking<Unit>{val f=ChatFixture();val e=f.remoteMessage("received confidential text");f.beforeAck={val m=f.memory.document.chat!!.message(e.message_id);assertEquals("received confidential text",m.text);assertNotNull(m.receipt);assertTrue(f.memory.document.chat!!.bindings.single().sessions.isNotEmpty())};f.sync();assertEquals(1,f.acknowledgments);assertTrue(f.memory.document.chat!!.message(e.message_id).acknowledged)}
    @Test fun failedInboxCommitNeverAcknowledgesOrConsumesSavedOneTimeKey()=runBlocking<Unit>{val f=ChatFixture();f.remoteMessage();val account=f.memory.document.chat!!.account;f.beforeCommit={if(it.chat!!.messages.any{m->m.direction==ChatDirection.INCOMING})f.memory.failWrite=true};expectFailure("STORAGE_UNAVAILABLE"){runBlocking{f.sync()}};assertEquals(0,f.acknowledgments);assertEquals(account,f.memory.document.chat!!.account);assertTrue(f.memory.document.chat!!.messages.isEmpty())}
    @Test fun lostAckReplyKeepsInboxAndRetriesSameSavedReceipt()=runBlocking<Unit>{val f=ChatFixture();val e=f.remoteMessage();f.afterAck={fail("PEER_TIMEOUT")};expectFailure("PEER_TIMEOUT"){runBlocking{f.sync()}};val r=f.memory.document.chat!!.message(e.message_id).receipt;f.reopen();f.engine.recover();f.afterAck={};f.sync();assertEquals(r,f.memory.document.chat!!.message(e.message_id).receipt);assertTrue(f.memory.document.chat!!.message(e.message_id).acknowledged);assertEquals(1,f.memory.document.chat!!.messages.size);assertEquals(2,f.acknowledgments)}
    @Test fun duplicatePullUsesReceiptWithoutReDecrypting()=runBlocking<Unit>{val f=ChatFixture();val e=f.remoteMessage();f.sync();val sessions=f.memory.document.chat!!.bindings.single().sessions;val receipt=f.memory.document.chat!!.message(e.message_id).receipt;f.remoteOutbox+=e;f.sync();assertEquals(1,f.memory.document.chat!!.messages.size);assertEquals(sessions,f.memory.document.chat!!.bindings.single().sessions);assertEquals(receipt,f.memory.document.chat!!.message(e.message_id).receipt);assertEquals(2,f.acknowledgments)}
    @Test fun sameIdDifferentEnvelopeIsAConflictNotNewDelivery()=runBlocking<Unit>{val f=ChatFixture();val e=f.remoteMessage();f.sync();f.remoteOutbox+=e.copy(ciphertext="AQID");expectFailure("MESSAGE_ID_CONFLICT"){runBlocking{f.sync()}};assertEquals(1,f.memory.document.chat!!.messages.size);assertEquals(1,f.acknowledgments)}
    @Test fun changedPinnedCryptoIdentityBlocksWithoutReset()=runBlocking<Unit>{val f=ChatFixture();f.sync();val before=f.memory.document.chat!!;val a=f.crypto.create();val b=f.crypto.bundle(a.account,f.peerId,f.memory.document.deviceId);f.remoteBundle=b.bundle;f.remoteAccount=b.account;expectFailure("CHAT_KEY_CHANGED"){runBlocking{f.sync()}};assertEquals(before.account,f.memory.document.chat!!.account);assertEquals(before.bindings,f.memory.document.chat!!.bindings)}
    @Test fun grantChangeBetweenResponseAndCommitDiscardsCandidate()=runBlocking<Unit>{val f=ChatFixture();f.remoteMessage();f.afterPull={f.memory.document=f.memory.document.replace(f.memory.document.peer(f.peerId).copy(remoteRevision=2,remoteEpoch=2))};expectFailure("CHAT_ACCESS_CHANGED"){runBlocking{f.sync()}};assertTrue(f.memory.document.chat!!.messages.isEmpty());assertEquals(0,f.acknowledgments)}
    @Test fun foregroundGuardRejectsWorkInsideDurableMutation()=runBlocking<Unit>{val f=ChatFixture();f.queue();var calls=0;expectFailure("CHAT_STOPPED"){runBlocking{f.sync{calls++;if(calls>=4)fail("CHAT_STOPPED")}}};assertTrue(f.pushed.isEmpty());assertNull(f.memory.document.chat!!.messages.single().envelope)}
    @Test fun fullHistoryNeverEvictsOrAcknowledgesNewContent()=runBlocking<Unit>{val f=ChatFixture();repeat(ChatRules.MAX_MESSAGES){f.queue("message $it")};expectFailure("CHAT_HISTORY_FULL"){runBlocking{f.queue()}};assertEquals(ChatRules.MAX_MESSAGES,f.memory.document.chat!!.messages.size)}
    @Test fun retriesHaveABudgetAndNeedReviewedReset()=runBlocking<Unit>{val f=ChatFixture();val m=f.queue();f.beforePush={fail("PEER_TIMEOUT")};repeat(3){expectFailure("PEER_TIMEOUT"){runBlocking{f.sync()}};f.clock+=5000};assertEquals(3,f.memory.document.chat!!.message(m.id).attempts);f.beforePush={};f.sync();assertEquals(ChatStatus.UNCERTAIN,f.memory.document.chat!!.message(m.id).status);expectFailure("LOCAL_CONFIRMATION_REQUIRED"){runBlocking{f.engine.retry(m.id,false)}};f.engine.retry(m.id,true);f.sync();assertEquals(ChatStatus.DELIVERED,f.memory.document.chat!!.message(m.id).status)}
    @Test fun cancelBeforeEncryptionIsNotSentButAfterSubmissionRemainsUnconfirmed()=runBlocking<Unit>{val f=ChatFixture();val a=f.queue();f.engine.cancel(a.id,true);assertEquals(ChatStatus.CANCELLED_NOT_SENT,f.memory.document.chat!!.message(a.id).status);val b=f.queue();f.afterPush={fail("PEER_TIMEOUT")};expectFailure{runBlocking{f.sync()}};f.engine.cancel(b.id,true);assertEquals(ChatStatus.CANCELLED_UNCONFIRMED,f.memory.document.chat!!.message(b.id).status);f.afterPush={};f.clock+=5000;f.sync();assertEquals(1,f.pushed.size)}
    @Test fun restartDoesNotSendOrReencryptAnything()=runBlocking<Unit>{val f=ChatFixture();f.queue();f.reopen();f.engine.recover();assertTrue(f.pushed.isEmpty());assertNull(f.memory.document.chat!!.messages.single().envelope)}
    @Test fun renewedPairingNeedsConsentAndOldMessagesNeverReplay()=runBlocking<Unit>{val f=ChatFixture();val m=f.queue();val account=f.memory.document.chat!!.account;val p=f.memory.document.peer(f.peerId);f.memory.document=f.memory.document.replace(p.copy(attemptId=UUID.randomUUID().toString(),localEpoch=p.localEpoch+1));expectFailure("CHAT_SCOPE_CHANGED"){runBlocking{f.sync()}};expectFailure("LOCAL_CONFIRMATION_REQUIRED"){runBlocking{f.engine.enablePeer(f.peerId,false)}};f.engine.enablePeer(f.peerId,true);f.sync();assertTrue(f.pushed.isEmpty());assertEquals(account,f.memory.document.chat!!.account);expectFailure("CHAT_PAIRING_CHANGED"){runBlocking{f.engine.retry(m.id,true)}}}
    @Test fun localReadFlagIsNotARemoteReadReceipt()=runBlocking<Unit>{val f=ChatFixture();val e=f.remoteMessage();f.sync();val receipt=f.memory.document.chat!!.message(e.message_id).receipt;assertTrue(f.memory.document.chat!!.message(e.message_id).unread);f.engine.markRead(f.peerId);assertFalse(f.memory.document.chat!!.message(e.message_id).unread);assertEquals(receipt,f.memory.document.chat!!.message(e.message_id).receipt);assertEquals("delivered",receipt!!.state)}
    @Test fun draftRoundTripDoesNotCreateNetworkWork()=runBlocking<Unit>{val f=ChatFixture();f.engine.saveDraft(f.peerId,"encrypted-draft sentinel");f.reopen();assertEquals("encrypted-draft sentinel",f.memory.document.chat!!.drafts.single().text);assertTrue(f.pushed.isEmpty());assertTrue(f.memory.document.chat!!.messages.isEmpty())}
    @Test fun twoIndependentPrekeySessionsAreRetainedAndReusable()=runBlocking<Unit>{val f=ChatFixture();val incoming=f.remoteMessage("remote prekey first");val outgoing=f.queue("local prekey before receiving");f.sync();assertEquals(2,f.memory.document.chat!!.bindings.single().sessions.size);assertEquals(2,f.remoteSessions.size);assertTrue(f.memory.document.chat!!.message(incoming.message_id).acknowledged);assertEquals(ChatStatus.DELIVERED,f.memory.document.chat!!.message(outgoing.id).status);f.remoteMessage("remote second on its session");f.queue("local second on its session");f.sync();assertEquals(4,f.memory.document.chat!!.messages.size);verifyProtectedChat(f.memory.document,f.crypto)}
    @Test fun oneExplicitBatchNeverDrainsMoreThanThreeOutgoingTexts()=runBlocking<Unit>{val f=ChatFixture();repeat(5){f.queue("queued $it")};f.sync();assertEquals(3,f.pushed.size);assertEquals(2,f.memory.document.chat!!.messages.count{it.status==ChatStatus.QUEUED});f.sync();assertEquals(5,f.pushed.size)}
    @Test fun aFullInboxDoesNotAcknowledgeOrConsumeTheIncomingSession()=runBlocking<Unit>{val f=ChatFixture();repeat(32){f.queue("retained $it")};f.remoteMessage();var before:ChatState?=null;f.afterPull={before=f.memory.document.chat};expectFailure("CHAT_HISTORY_FULL"){runBlocking{f.sync()}};assertEquals(0,f.acknowledgments);assertEquals(before!!.account,f.memory.document.chat!!.account);assertEquals(before!!.bindings,f.memory.document.chat!!.bindings);assertEquals(32,f.memory.document.chat!!.messages.size)}
    @Test fun invalidRemoteReceiptCannotBecomeDeliveredAndExactRetryCanRecover()=runBlocking<Unit>{val f=ChatFixture();val m=f.queue();val bad=object:ChatGateway by f.gateway{override suspend fun push(ticket:ChatTicket,delivery:ChatDelivery):ChatResult<ChatReceipt>{val r=f.gateway.push(ticket,delivery);return r.copy(value=r.value.copy(digest="f".repeat(64)))}};expectFailure("INVALID_RECEIPT"){runBlocking{f.engine.sync(f.peerId,bad)}};assertEquals(ChatStatus.UNCERTAIN,f.memory.document.chat!!.message(m.id).status);assertNull(f.memory.document.chat!!.message(m.id).receipt);f.clock+=5000;f.sync();assertEquals(ChatStatus.DELIVERED,f.memory.document.chat!!.message(m.id).status);assertEquals(f.pushed[0],f.pushed[1])}

}
